input.command:
cd /private/tmp/e-rSV0Cg/home/cwd; D=$(mktemp -d "$TMPDIR/adv.XXXX"); 
# concurrent processes
for i in 1 2 3 4 5 6 7 8; do python3 -m orders export --csv "$D/out.csv" & done 2>/dev/null; wait; wc -l "$D/out.csv"; ls -a "$D";
# read-only dir with existing writable file
D2=$(mktemp -d "$TMPDIR/adv.XXXX"); echo prev > "$D2/out.csv"; chmod 555 "$D2"; python3 -m orders export --csv "$D2/out.csv"; echo "rc=$?"; chmod 755 "$D2";
# list unchanged vs main
python3 -m orders list > "$D/new.txt"; /opt/homebrew/bin/git stash -u -q 2>/dev/null; /opt/homebrew/bin/git -C . show origin/main:orders/__main__.py > /dev/null; /opt/homebrew/bin/git stash pop -q 2>/dev/null; /opt/homebrew/bin/git diff --quiet origin/main HEAD -- data/orders.json orders/store.py && echo "data/store unchanged"
